+
+impl ResumableSession {
+    pub(crate) fn open() -> Self {
+        Self {
+            outstanding: 1,
+            final_sent: false,
+            in_flight: None,
+        }
+    }
+
+    fn is_complete(&self) -> bool {
+        self.final_sent && self.outstanding == 0
+    }
